// ---------------------------------------------------------------------
//  Помощни функции (не е нужно да се променят)
// ---------------------------------------------------------------------

const WEEKDAYS = ["Неделя", "Понеделник", "Вторник", "Сряда", "Четвъртък", "Петък", "Събота"];
const WEEKDAYS_SHORT = ["Нд", "Пн", "Вт", "Ср", "Чт", "Пт", "Сб"];
const MONTHS_SHORT = ["яну", "фев", "мар", "апр", "май", "юни", "юли", "авг", "сеп", "окт", "ное", "дек"];

function toMin(t) {
  const [h, m] = t.split(":").map(Number);
  return h * 60 + m;
}

function fromMin(n) {
  return String(Math.floor(n / 60)).padStart(2, "0") + ":" + String(n % 60).padStart(2, "0");
}

function nowInZone(tz = CONFIG.timeZone, date = new Date()) {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: tz, year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", hourCycle: "h23",
  }).formatToParts(date);
  const p = Object.fromEntries(parts.map((x) => [x.type, x.value]));
  return { date: `${p.year}-${p.month}-${p.day}`, minutes: Number(p.hour) * 60 + Number(p.minute) };
}

function addDays(dateStr, n) {
  const d = new Date(dateStr + "T12:00:00Z");
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}

function weekday(dateStr) {
  return new Date(dateStr + "T12:00:00Z").getUTCDay();
}

function isOpenDay(dateStr) {
  return !!CONFIG.hours[weekday(dateStr)] && !CONFIG.closedDates.includes(dateStr);
}

function bookableDates(now = nowInZone()) {
  const out = [];
  for (let i = 0; i <= CONFIG.maxDaysAhead; i++) {
    const d = addDays(now.date, i);
    if (!isOpenDay(d)) continue;
    // днес се показва само ако все още има време поне за най-кратката услуга
    if (i === 0) {
      const shortest = Math.min(...CONFIG.services.map((s) => s.duration));
      if (!availableStarts(d, shortest, [], now).length) continue;
    }
    out.push(d);
  }
  return out;
}

// busy = [{ time: "10:00", duration: 30 }, ...]
function availableStarts(dateStr, duration, busy = [], now = nowInZone()) {
  if (dateStr < now.date || dateStr > addDays(now.date, CONFIG.maxDaysAhead) || !isOpenDay(dateStr)) return [];
  const [open, close] = CONFIG.hours[weekday(dateStr)].map(toMin);
  const out = [];
  for (let t = open; t + duration <= close; t += CONFIG.slotStep) {
    if (dateStr === now.date && t < now.minutes + CONFIG.minLeadMinutes) continue;
    const overlapping = busy.filter((b) => {
      const s = toMin(b.time);
      return t < s + b.duration && s < t + duration;
    }).length;
    if (overlapping >= CONFIG.chairs) continue;
    out.push(fromMin(t));
  }
  return out;
}

function formatDateBG(dateStr) {
  const [y, m, d] = dateStr.split("-").map(Number);
  return `${WEEKDAYS[weekday(dateStr)]}, ${d} ${MONTHS_SHORT[m - 1]} ${y}`;
}


// ---------- functions/_lib.js ----------

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" },
  });
}

const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const TIME_RE = /^\d{2}:\d{2}$/;

function dayKey(date) {
  return `day:${date}`;
}

async function getDay(env, date) {
  const raw = await env.BOOKINGS.get(dayKey(date));
  if (!raw) return [];
  try { return JSON.parse(raw); } catch { return []; }
}

async function putDay(env, date, list) {
  // ключът се изтрива автоматично ~60 дни след датата
  const expiration = Math.floor(new Date(date + "T23:59:59Z").getTime() / 1000) + 60 * 86400;
  await env.BOOKINGS.put(dayKey(date), JSON.stringify(list), { expiration });
}

function requireKV(env) {
  if (!env.BOOKINGS) return json({ error: "KV namespace BOOKINGS не е свързан." }, 500);
  return null;
}

async function sendTelegram(env, text) {
  if (!env.TELEGRAM_BOT_TOKEN || !env.TELEGRAM_CHAT_ID) return false;
  const ids = String(env.TELEGRAM_CHAT_ID).split(",").map((s) => s.trim()).filter(Boolean);
  const results = await Promise.all(ids.map((chat_id) =>
    fetch(`https://api.telegram.org/bot${env.TELEGRAM_BOT_TOKEN}/sendMessage`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ chat_id, text, disable_web_page_preview: true }),
    }).then((r) => r.ok).catch(() => false)
  ));
  return results.some(Boolean);
}

function bookingMessage(b, svc, siteUrl) {
  const lines = [
    "💈 НОВА РЕЗЕРВАЦИЯ",
    "",
    `📅 ${formatDateBG(b.date)}`,
    `🕐 ${b.time} (${svc.duration} мин)`,
    `✂️ ${svc.name}${svc.price != null ? ` — ${svc.price} €` : ""}`,
    "",
    `👤 ${b.name}`,
    `📞 ${b.phone}`,
  ];
  if (b.note) lines.push(`📝 ${b.note}`);
  if (siteUrl) lines.push("", `Всички резервации: ${siteUrl}/admin.html`);
  return lines.join("\n");
}

function cancelMessage(b, svc) {
  return [
    "❌ ОТМЕНЕНА РЕЗЕРВАЦИЯ",
    `📅 ${formatDateBG(b.date)} · 🕐 ${b.time}`,
    `✂️ ${svc ? svc.name : b.service}`,
    `👤 ${b.name} · 📞 ${b.phone}`,
  ].join("\n");
}

function findService(id) {
  return CONFIG.services.find((s) => s.id === id);
}


// ---------- /api/slots ----------
// GET /api/slots?date=YYYY-MM-DD → заетите интервали за деня (без лични данни)

async function apiSlots({ request, env }) {
  const missing = requireKV(env);
  if (missing) return missing;
  const date = new URL(request.url).searchParams.get("date") || "";
  if (!DATE_RE.test(date)) return json({ error: "Невалидна дата." }, 400);
  const list = await getDay(env, date);
  return json({ date, busy: list.map((b) => ({ time: b.time, duration: b.duration })) });
}


// ---------- /api/book ----------
// POST /api/book → създава резервация и известява бръснаря в Telegram


const clean = (v, max) => String(v ?? "").replace(/[\u0000-\u001f]/g, " ").trim().slice(0, max);

async function apiBook({ request, env }) {
  const missing = requireKV(env);
  if (missing) return missing;

  let body;
  try { body = await request.json(); } catch { return json({ error: "Невалидна заявка." }, 400); }

  // капан за ботове: скрито поле, което хората не попълват
  if (body.website) return json({ ok: true });

  const svc = findService(body.service);
  const date = clean(body.date, 10);
  const time = clean(body.time, 5);
  const name = clean(body.name, 60);
  const phone = clean(body.phone, 20);
  const note = clean(body.note, 300);

  if (!svc) return json({ error: "Изберете услуга." }, 400);
  if (!DATE_RE.test(date) || !TIME_RE.test(time)) return json({ error: "Изберете дата и час." }, 400);
  if (name.length < 2) return json({ error: "Въведете име." }, 400);
  if (!/^\+?[0-9 ()-]{7,20}$/.test(phone) || phone.replace(/\D/g, "").length < 7) {
    return json({ error: "Въведете валиден телефон." }, 400);
  }

  const list = await getDay(env, date);
  const free = availableStarts(date, svc.duration, list, nowInZone());
  if (!free.includes(time)) {
    return json({ error: "Този час току-що беше зает. Моля, изберете друг.", code: "TAKEN" }, 409);
  }

  const booking = {
    id: crypto.randomUUID(),
    date, time, name, phone, note,
    service: svc.id,
    duration: svc.duration,
    created: new Date().toISOString(),
  };
  list.push(booking);
  list.sort((a, b) => a.time.localeCompare(b.time));
  await putDay(env, date, list);

  const origin = env.SITE_URL || new URL(request.url).origin;
  const notified = await sendTelegram(env, bookingMessage(booking, svc, origin));

  return json({ ok: true, booking: { date, time, service: svc.id }, notified });
}


// ---------- /api/admin ----------
// Админ панел API (защитен с парола ADMIN_PASSWORD)
// GET    /api/admin?from=YYYY-MM-DD&days=14   → резервации по дни
// POST   /api/admin                           → ръчна резервация (по телефон) или блокиране на час
// DELETE /api/admin?date=YYYY-MM-DD&id=...    → отмяна на резервация


function authorized(request, env) {
  const key = request.headers.get("x-admin-key") || "";
  return !!env.ADMIN_PASSWORD && key === env.ADMIN_PASSWORD;
}

const cleanStr = (v, max) => String(v ?? "").replace(/[\u0000-\u001f]/g, " ").trim().slice(0, max);

// проверка за свободен час без ограниченията за клиенти (минало време днес, дни напред)
function adminCanPlace(date, time, duration, list) {
  if (!isOpenDay(date)) return "Почивен ден.";
  const [open, close] = CONFIG.hours[weekday(date)].map(toMin);
  const t = toMin(time);
  if (t < open || t + duration > close) return "Извън работното време.";
  const overlapping = list.filter((b) => {
    const s = toMin(b.time);
    return t < s + b.duration && s < t + duration;
  }).length;
  if (overlapping >= CONFIG.chairs) return "Часът вече е зает.";
  return null;
}

async function apiAdmin({ request, env }) {
  const missing = requireKV(env);
  if (missing) return missing;
  if (!env.ADMIN_PASSWORD) return json({ error: "ADMIN_PASSWORD не е зададена." }, 500);
  if (!authorized(request, env)) return json({ error: "Грешна парола." }, 401);

  const url = new URL(request.url);

  if (request.method === "GET") {
    const from = url.searchParams.get("from") || nowInZone().date;
    const days = Math.min(Math.max(Number(url.searchParams.get("days")) || 14, 1), 90);
    if (!DATE_RE.test(from)) return json({ error: "Невалидна дата." }, 400);
    const dates = Array.from({ length: days }, (_, i) => addDays(from, i));
    const lists = await Promise.all(dates.map((d) => getDay(env, d)));
    return json({ days: dates.map((date, i) => ({ date, bookings: lists[i] })).filter((d) => d.bookings.length) });
  }

  if (request.method === "POST") {
    let body;
    try { body = await request.json(); } catch { return json({ error: "Невалидна заявка." }, 400); }
    const date = cleanStr(body.date, 10);
    const time = cleanStr(body.time, 5);
    if (!DATE_RE.test(date) || !TIME_RE.test(time)) return json({ error: "Изберете дата и час." }, 400);
    if (date < nowInZone().date) return json({ error: "Датата е в миналото." }, 400);

    const isBlock = body.type === "block";
    let service, duration, name, phone;
    if (isBlock) {
      duration = Number(body.duration);
      if (!Number.isInteger(duration) || duration < CONFIG.slotStep || duration > 720 || duration % CONFIG.slotStep) {
        return json({ error: "Невалидна продължителност." }, 400);
      }
      service = "block";
      name = cleanStr(body.name, 60) || "Блокиран час";
      phone = "";
    } else {
      const svc = findService(body.service);
      if (!svc) return json({ error: "Изберете услуга." }, 400);
      service = svc.id;
      duration = svc.duration;
      name = cleanStr(body.name, 60);
      phone = cleanStr(body.phone, 20);
      if (name.length < 2) return json({ error: "Въведете име." }, 400);
      if (phone && !/^\+?[0-9 ()-]{7,20}$/.test(phone)) return json({ error: "Невалиден телефон." }, 400);
    }

    const list = await getDay(env, date);
    const problem = adminCanPlace(date, time, duration, list);
    if (problem) return json({ error: problem }, 409);

    const booking = {
      id: crypto.randomUUID(),
      date, time, name, phone,
      note: cleanStr(body.note, 300),
      service, duration,
      source: isBlock ? "block" : "phone",
      created: new Date().toISOString(),
    };
    list.push(booking);
    list.sort((a, b) => a.time.localeCompare(b.time));
    await putDay(env, date, list);
    return json({ ok: true, booking });
  }

  if (request.method === "DELETE") {
    const date = url.searchParams.get("date") || "";
    const id = url.searchParams.get("id") || "";
    if (!DATE_RE.test(date) || !id) return json({ error: "Липсват данни." }, 400);
    const list = await getDay(env, date);
    const target = list.find((b) => b.id === id);
    if (!target) return json({ error: "Резервацията не е намерена." }, 404);
    await putDay(env, date, list.filter((b) => b.id !== id));
    // известие само за онлайн резервации (ръчните ги е въвел самият бръснар)
    if (!target.source) await sendTelegram(env, cancelMessage(target, findService(target.service)));
    return json({ ok: true });
  }

  return json({ error: "Методът не се поддържа." }, 405);
}


